    "raciocinio": "Extraí duas funções auxiliares: parseAndValidate, que limpa os campos e já
verifica se nome e email estão presentes, retornando a lista de campos ausentes;
e normalizeFields, que aplica lowercase no email, uppercase no plano com fallback
'FREE', e interpreta a idade como inteiro. O importUsers passa a orquestrar
essas duas funções sem duplicar lógica inline.

Essa separação melhora a legibilidade e torna normalizeFields diretamente
testável com objetos já validados.
",
    "codigo": "// userImporter.js

function parseAndValidate(row) {
  const nome  = (row.nome  || '').trim();
  const email = (row.email || '').trim();
  const missing = [];
  if (!nome)  missing.push('nome');
  if (!email) missing.push('email');
  return { nome, email, rawIdade: row.idade, rawPlano: row.plano, missing };
}

function normalizeFields(parsed) {
  const idade = parseInt(parsed.rawIdade, 10);
  const plano = (parsed.rawPlano || '').trim().toUpperCase() || 'FREE';
  return {
    nome:  parsed.nome,
    email: parsed.email.toLowerCase(),
    idade: isNaN(idade) ? 0 : idade,
    plano,
  };
}

function importUsers(rawRows) {
  const valid  = [];
  const errors = [];

  for (let i = 0; i < rawRows.length; i++) {
    const lineNumber = i + 1;
    const parsed = parseAndValidate(rawRows[i]);

    if (parsed.missing.length > 0) {
      errors.push({ line: lineNumber, missingFields: parsed.missing });
      continue;
    }

    valid.push(normalizeFields(parsed));
  }

  return { valid, errors };
}

module.exports = { importUsers };
